// Landmarks of Rishon LeZion: hand-built, stylized, parody-named set pieces.
//
// Positions come from OpenStreetMap (Overpass/Nominatim, re-checked 2026-10-15) and
// go through project() in src/geo.js. Every lat/lon below carries its OSM id.
// Tags used in comments:
//   VERIFIED  position from an OSM feature and the look from a dated photo
//             (Wikimedia Commons, file name given) or a dated news source.
//   OSM       position from an OSM feature; look stylized, not photo-checked.
//   INFERRED  placed by reasoning from nearby OSM features; no direct source.
//   ASSUMED   chosen by hand.
//
// Sizing at SCALE 1.2 (world units per metre): building footprints come straight from
// the OSM outlines; building heights are real metres x SCALE; props (benches, umbrellas,
// dinosaurs, gondolas) are sized to the ~5-unit avatar, not to the map.
//
// Draw calls: static parts of each landmark are merged into one vertex-coloured mesh;
// only animated parts and canvas-textured signs are separate meshes.

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { project, SCALE } from '../geo.js';

// Optional modules owned by other agents. Both are guarded: without them the landmarks
// still build, with English sign text and flat ground.
let _t = null;
try { ({ t: _t } = await import('../i18n.js')); } catch (e) { _t = null; }
let groundAt = () => 0, hasTerrain = false, surfaceKind = null, terrainMetaFn = null;
try {
  const m = await import('./terrain.js');
  if (typeof m.groundAt === 'function') { groundAt = m.groundAt; hasTerrain = true; }
  if (typeof m.surfaceAt === 'function') surfaceKind = m.surfaceAt; // 'land' | 'sand' | 'sea'
  if (typeof m.terrainMeta === 'function') terrainMetaFn = m.terrainMeta;
} catch (e) { /* no terrain yet: flat world */ }
// Test hook for the preview page (fake hills) until the real terrain lands.
export function setGroundAt(fn) { groundAt = fn; hasTerrain = typeof fn === 'function'; }
const gAt = (x, z) => { const y = groundAt(x, z); return Number.isFinite(y) ? y : 0; };
// Sign canvases use the game's Hebrew-capable font; wait briefly so the first build has it.
try {
  if (typeof document !== 'undefined' && document.fonts && document.fonts.load) {
    await Promise.race([document.fonts.load('900 64px Rubik'), new Promise((r) => setTimeout(r, 1500))]);
  }
} catch (e) { /* fall back to whatever font is available */ }

// Display text: keys live in data/i18n/*.json; the English parody text here is the fallback.
function tx(key, fallback) {
  if (!_t) return fallback;
  try {
    const v = _t(key, null, fallback);
    return v == null || v === key || v === '' ? fallback : v;
  } catch (e) { return fallback; }
}

