// ---- Round 5 (2026-10-16) ----
// Azrieli Rishonim mall and office tower: OSM way 83910004 (building, layer 1, shop=mall, "Azrieli
// Rishonim"), on the former traffic island between Route 412 (west), Route 431 with the railway in
// its median (south) and Sderot Nim (north-east), right beside HaRishonim station (way 96030054).
// Look VERIFIED from Commons "Azrieli Rishonim Mall.jpg" and "Rishonim train station 02.jpg" (drone
// views, about 2022), "Azrieli Rishonim 2019 - view from highway 1.jpg" and "112884 azrieli rishonim
// PikiWiki Israel.jpg": a long white lozenge wrapped in triangulated white panels, a dark green glass
// band with shop signs along the south-west face over Route 412/431, the pointed south-east end
// glazed with one big dark window and raised on columns over the bus terminal (buses park under it),
// and at the north-west end a 14-storey office tower of two white slabs split by a glass slit, joined
// to the mall roof by folded white "petals". Architect's text (Mann-Shinar, "Oneness"; theplan.it
// award page, checked 2026-10-16): a three-floor mall, half the footprint raised on columns for bus
// parking and a pedestrian passage. Tower and mall heights INFERRED from the photos (mall ~20 m,
// tower roof ~80 m above the plaza).
// Cliff lookout over Route 431 (founder, 2026-10-16): the Homa uMigdal roundabout (OSM way
// 164935078) closes Kiryat Ganim / Neot Ashlim at the top of "Dunes Park" (OSM leisure=park way
// 118552804), above Route 431. The terrain bake cuts 431 under a near-vertical kurkar wall there
// (commit 85be8ae, docs/CLIFF_431.md: Mapillary 2021 shows a shotcrete kurkar wall with a leaning
// tree on top; SRTM predates the 2009 cutting). Its data in data/terrain.json cliffs[0]: the level
// lookout at 77.42 u, the road below at 55.2-56.1, the top edge polyline (-266.2,1935.4) ->
// (-114.9,2057.4). The OSM picnic site (tourism=picnic_site, node 4007362279) sits between the
// roundabout and the edge, benches about (-186.8,1967.5) and (-211.5,1963.1); the giant tree stands
// at (-199.1,1979.5), about 8 u from the edge, leaning toward the road along (-0.628, 0.778).
// Railing, tables and the tree's shape ASSUMED (the founder's description; his photos are open).
const LOOKOUT_C = [-197, 1970];                       // world units (picnic site, by the tree)
const LOOKOUT_TREE = [-199.1, 1979.5];
const LOOKOUT_DIR = [-0.628, 0.778];                  // toward the road below
const LOOKOUT_BENCHES = [[-186.8, 1967.5], [-211.5, 1963.1], [-174.5, 1978.5]];
const LOOKOUT_EDGE = [[-266.2, 1935.4], [-114.9, 2057.4]]; // fallback when terrain.json has no cliffs
