// Old poi ids that still resolve. Quests may look these up through resolvePoiId().
export const POI_ALIASES = { cinema_planetish: 'yes_planet', cinema: 'cinema_city', dinosaurs: 'dino_park', well: 'founders_well', matzanu_mayim: 'founders_well', well_house: 'founders_well', kiryat_ganim_lookout: 'cliff_lookout', lookout: 'cliff_lookout', rova: 'harova', mitcham_harova: 'harova', activipark: 'neot_shikma_karting', ecological_garden: 'eco_garden' };
export function resolvePoiId(id) { return POI_ALIASES[id] || id; }

// ---------------------------------------------------------------------------
// Small math helpers (world coords: x east, z south).
// ---------------------------------------------------------------------------
const P = (ll) => { const p = project(ll[0], ll[1]); return [p.x, p.z]; };
const projPoly = (list) => list.map(P);
const RM = SCALE; // world units per real metre, for real-size architecture
// Headroom for the avatars (round 6: people stood taller than the surf club roof and the Gan HaIr
// chess shed). Avatars are about 4.3 u (0.85) and drawn bigger than real people against the map, so
// covered spaces people walk into are sized to them, not to real metres: clear height under any
// roof or beam >= HEADROOM, doors DOOR_H tall.
const HEADROOM = 6.4, DOOR_H = 5.2;

function centroid(poly) {
  let x = 0, z = 0;
  for (const p of poly) { x += p[0]; z += p[1]; }
  return [x / poly.length, z / poly.length];
}

// A placement frame: local +z faces the direction given by ry (three.js convention).
function frame(x, z, ry = 0) {
  const c = Math.cos(ry), s = Math.sin(ry);
  const w = (lx, lz) => [x + lx * c + lz * s, z - lx * s + lz * c];
  return {
    x, z, ry, w,
    rect(cx, cz, wd, dp, r = 0) {
      const cr = Math.cos(r), sr = Math.sin(r);
      return [[-1, -1], [1, -1], [1, 1], [-1, 1]].map(([a, b]) => {
        const lx = a * wd / 2, lz = b * dp / 2;
        return w(cx + lx * cr + lz * sr, cz - lx * sr + lz * cr);
      });
    },
    circle(cx, cz, r, n = 8) {
      const out = [];
      for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; out.push(w(cx + Math.cos(a) * r, cz + Math.sin(a) * r)); }
      return out;
    },
  };
}

function pointInPoly(x, z, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, zi] = poly[i], [xj, zj] = poly[j];
    if ((zi > z) !== (zj > z) && x < ((xj - xi) * (z - zi)) / (zj - zi) + xi) inside = !inside;
  }
  return inside;
}

// Longest polygon edge whose outward normal points roughly along dir.
function pickEdge(poly, dir, minDot = 0.5) {
  let best = null;
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length];
    const dx = b[0] - a[0], dz = b[1] - a[1], len = Math.hypot(dx, dz);
    if (len < 1e-6) continue;
    let nx = dz / len, nz = -dx / len;
    const mx = (a[0] + b[0]) / 2, mz = (a[1] + b[1]) / 2;
    if (pointInPoly(mx + nx * 0.5, mz + nz * 0.5, poly)) { nx = -nx; nz = -nz; }
    const score = (nx * dir[0] + nz * dir[1]) > minDot ? len : -1;
    if (score > 0 && (!best || score > best.len)) best = { a, b, mx, mz, nx, nz, len, ry: Math.atan2(nx, nz) };
  }
  return best;
}

// Frame of the edge a->b of poly with its outward normal; lx(t) is the along-edge coordinate
// (for edgeAt/edgeSign) of the point a fraction t from a to b.
function edgeOf(poly, a, b) {
  const dx = b[0] - a[0], dz = b[1] - a[1], len = Math.hypot(dx, dz) || 1e-6;
  let nx = dz / len, nz = -dx / len;
  const mx = (a[0] + b[0]) / 2, mz = (a[1] + b[1]) / 2;
  if (pointInPoly(mx + nx * 0.5, mz + nz * 0.5, poly)) { nx = -nx; nz = -nz; }
  const ry = Math.atan2(nx, nz), s = Math.sign(Math.cos(ry) * dx - Math.sin(ry) * dz) || 1;
  return { a, b, mx, mz, nx, nz, len, ry, lx: (t) => s * (t - 0.5) * len, p: (t, d = 0) => [a[0] + dx * t + nx * d, a[1] + dz * t + nz * d] };
}

// Keep the part of a polygon where (p - p0) . n >= d (one Sutherland-Hodgman pass).
// pickEdge, returned as a full edgeOf frame (with lx/p helpers), or null.
function pickEdgeOf(poly, dir, minDot = 0.5) { const e = pickEdge(poly, dir, minDot); return e ? edgeOf(poly, e.a, e.b) : null; }

function clipHalf(poly, p0, n, d) {
  const out = [], f = (p) => (p[0] - p0[0]) * n[0] + (p[1] - p0[1]) * n[1] - d;
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i], b = poly[(i + 1) % poly.length], fa = f(a), fb = f(b);
    if (fa >= 0) out.push(a);
    if ((fa >= 0) !== (fb >= 0)) { const t = fa / (fa - fb); out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]); }
  }
  return out;
}

// Clip a polygon back from a straight street (two lat/lon points, half-width hw in units),
// keeping the side that holds the polygon's centroid, with a 0.8 u kerb gap.
function clipOffRoad(poly, ll, hw) {
  const [a, b] = ll.map(P), dx = b[0] - a[0], dz = b[1] - a[1], l = Math.hypot(dx, dz) || 1;
  let n = [-dz / l, dx / l];
  const [cx, cz] = centroid(poly);
  if ((cx - a[0]) * n[0] + (cz - a[1]) * n[1] < 0) n = [-n[0], -n[1]];
  return clipHalf(poly, a, n, hw + 1.5);
}
// True when a point keeps hw + 0.8 u clear of the street's line on the polygon side.
function clearOfRoad(pt, ll, hw, ref) {
  const [a, b] = ll.map(P), dx = b[0] - a[0], dz = b[1] - a[1], l = Math.hypot(dx, dz) || 1;
  let n = [-dz / l, dx / l];
  if ((ref[0] - a[0]) * n[0] + (ref[1] - a[1]) * n[1] < 0) n = [-n[0], -n[1]];
  return (pt[0] - a[0]) * n[0] + (pt[1] - a[1]) * n[1] >= hw + 0.8;
}

// Placement on an edge: lx along the edge, lz outward.
function edgeAt(e) {
  return (lx, y, lz, rx = 0, rz = 0, sx = 1, sy = sx, sz = sx) => M(e.mx + lx * Math.cos(e.ry) + lz * Math.sin(e.ry), y, e.mz - lx * Math.sin(e.ry) + lz * Math.cos(e.ry), rx, e.ry, rz, sx, sy, sz);
}

function lerpLine(line, lat) {
  for (let i = 0; i < line.length - 1; i++) {
    const a = line[i], b = line[i + 1];
    if (lat >= a[0] && lat <= b[0]) { const t = (lat - a[0]) / (b[0] - a[0]); return a[1] + (b[1] - a[1]) * t; }
  }
  return lat < line[0][0] ? line[0][1] : line[line.length - 1][1];
}

// Even spacing along a polyline (closed adds the closing edge).
function resample(pts, step, closed) {
  const src = closed ? [...pts, pts[0]] : pts;
  const out = [src[0].slice()];
  let carry = 0;
  for (let i = 0; i < src.length - 1; i++) {
    const [ax, az] = src[i], [bx, bz] = src[i + 1], len = Math.hypot(bx - ax, bz - az);
    let d = step - carry;
    while (d <= len) { const t = d / len; out.push([ax + (bx - ax) * t, az + (bz - az) * t]); d += step; }
    carry = len - (d - step);
  }
  if (closed && out.length > 2 && Math.hypot(out[0][0] - out[out.length - 1][0], out[0][1] - out[out.length - 1][1]) < step * 0.5) out.pop();
  return out;
}

// Chaikin corner cutting, to turn jagged OSM tracks into ride-able curves.
function smooth(pts, iterations, closed) {
  let p = pts;
  for (let k = 0; k < iterations; k++) {
    const out = [];
    const n = p.length, last = closed ? n : n - 1;
    if (!closed) out.push(p[0]);
    for (let i = 0; i < last; i++) {
      const a = p[i], b = p[(i + 1) % n];
      out.push([a[0] * 0.75 + b[0] * 0.25, a[1] * 0.75 + b[1] * 0.25], [a[0] * 0.25 + b[0] * 0.75, a[1] * 0.25 + b[1] * 0.75]);
    }
    if (!closed) out.push(p[n - 1]);
    p = out;
  }
  return p;
}

function scalePoly(poly, k) { const [cx, cz] = centroid(poly); return poly.map(([x, z]) => [cx + (x - cx) * k, cz + (z - cz) * k]); }

// Deterministic pseudo-random numbers so the world is the same every load.
function rng(seed) { let s = seed >>> 0; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }

// ---------------------------------------------------------------------------
// Layout: frames and footprints, computed at import so the city module can read
// LANDMARK_FOOTPRINTS without building any geometry.
// ---------------------------------------------------------------------------
const L = (() => {
  const ccW = projPoly(CINEMA_CITY_POLY);
  const dinoW = projPoly(DINO_POLY);
  const ypW = projPoly(YES_PLANET_POLY);
  const superW = projPoly(SUPERLAND_POLY);
  const mallW = projPoly(MALL_POLY);
  const wineryW = projPoly(WINERY_POLY);
  const pondW = projPoly(POND_POLY);
  const synW = projPoly(SYNAGOGUE_POLY);
  const towerW = projPoly(WATER_TOWER_POLY);
  const wellW = projPoly(WELL_SITE_POLY);
  const mdW = projPoly(MOSHE_DAYAN_POLY);
  const hrW = projPoly(HARISHONIM_POLY);
  const kioskW = projPoly(KIOSK_POLY);
  const [sax, saz] = P(SQUARE_A), [sbx, sbz] = P(SQUARE_B);
  const coastRy = (() => { const a = P(COAST_LINE[0]), b = P(COAST_LINE[COAST_LINE.length - 1]); return Math.atan2(b[0] - a[0], b[1] - a[1]); })();
  // Synagogue: facade on the polygon edge that faces the square (west).
  const synF = (() => { const [cx, cz] = centroid(synW); const e = pickEdge(synW.map(([x, z]) => [x - cx, z - cz]), [-1, 0]); return frame(cx, cz, e ? e.ry : -Math.PI / 2); })();
  const towerF = frame(...centroid(towerW), (() => { const [a, b] = [towerW[0], towerW[1]]; return Math.atan2(b[0] - a[0], b[1] - a[1]) + Math.PI / 2; })());
  return {
    cinemaCity: { f: frame(...centroid(ccW)), world: ccW },
    dino: { f: frame(...centroid(dinoW)), world: dinoW },
    yesPlanet: { f: frame(...centroid(ypW)), world: ypW },
    superland: { f: frame(...centroid(superW)), world: superW, gate: frame(...P(SL_ENTRANCE), -Math.PI / 2) },
    pond: { world: pondW, f: frame(...centroid(pondW)) },
    mall: { f: frame(...centroid(mallW)), world: mallW },
    winery: { f: frame(...centroid(wineryW)), world: wineryW },
    square: { f: frame((sax + sbx) / 2, (saz + sbz) / 2, Math.atan2(sbx - sax, sbz - saz) + Math.PI / 2), len: Math.hypot(sbx - sax, sbz - saz) },
    synagogue: { f: synF, world: synW },
    tower: { f: towerF, world: towerW },
    well: { f: frame(...centroid(wellW)), world: wellW, dropoff: frame(...P(WELL_DROPOFF_LL)) },
    ...(() => {
      const bboxRect = (...polys) => { const pts = polys.flat(); const xs = pts.map((p) => p[0]), zs = pts.map((p) => p[1]); return [[Math.min(...xs), Math.min(...zs)], [Math.max(...xs), Math.min(...zs)], [Math.max(...xs), Math.max(...zs)], [Math.min(...xs), Math.max(...zs)]]; };
      const ch = projPoly(CITY_HALL_POLY), chP = projPoly(CITY_HALL_PLAZA_POLY);
      const hA = projPoly(HEICHAL_A_POLY), hB = projPoly(HEICHAL_B_POLY), hP = HEICHAL_STREETS.reduce((p, ll) => clipOffRoad(p, ll, HEICHAL_STREET_HW), projPoly(HEICHAL_PLAZA_POLY));
      const sk = projPoly(SKATE_POLY), td = projPoly(TEDER_POLY), bc = projPoly(BEACH_COMPLEX_POLY);
      const chSeat = bboxRect(ch, chP), hSeat = bboxRect(hA, hB, hP), sSeat = bboxRect(sk, td);
      return {
        cityHall: { f: frame(...centroid(ch)), world: ch, plaza: chP, seat: chSeat },
        ganHair: { world: projPoly(GAN_HAIR_POLY) },
        heichal: { f: frame(...centroid(hSeat)), A: hA, B: hB, plaza: hP, seat: hSeat },
        skate: { f: frame(...centroid(sk)), skate: sk, teder: td, seat: sSeat },
        beachComplex: { f: frame(...centroid(bc)), world: bc },
        surfClub: (() => { const sc = projPoly(SURF_CLUB_POLY); return { f: frame(...centroid(sc)), world: sc, rect: bboxRect(sc) }; })(),
      };
    })(),
    mosheDayan: { f: frame(...centroid(mdW)), world: mdW, foot: (() => {
      // Footprint without the strip under the Sderot Moshe Dayan bridge deck (a carriageway).
      const band = scalePoly(projPoly([[31.987379, 34.75666], [31.987143, 34.757803], [31.987307, 34.757832], [31.987538, 34.756704]]), 1.15);
      const [cx, cz] = centroid(mdW);
      let best = null;
      for (let i = 0; i < band.length; i++) { const p = band[i], q = band[(i + 1) % band.length], m = [(p[0] + q[0]) / 2, (p[1] + q[1]) / 2], d = Math.hypot(m[0] - cx, m[1] - cz); if (!best || d < best.d) best = { p, q, d }; }
      const dx = best.q[0] - best.p[0], dz = best.q[1] - best.p[1], l = Math.hypot(dx, dz);
      let n = [-dz / l, dx / l];
      if ((cx - best.p[0]) * n[0] + (cz - best.p[1]) * n[1] < 0) n = [-n[0], -n[1]];
      const c = clipHalf(mdW, best.p, n, 12); // the deck and its parapets run about 8-11 u either side of the centre line
      return c.length >= 3 ? c : mdW;
    })() },
    founders: (() => {
      // Paved strips just outside the two carriageways, on the far side of each from the other.
      const lines = FOUNDERS_CW.map((l) => l.map(P));
      return lines.map((ln, i) => {
        const [a, b] = ln, o = lines[1 - i], om = [(o[0][0] + o[1][0]) / 2, (o[0][1] + o[1][1]) / 2];
        const dx = b[0] - a[0], dz = b[1] - a[1], l = Math.hypot(dx, dz);
        let n = [-dz / l, dx / l];
        if ((om[0] - a[0]) * n[0] + (om[1] - a[1]) * n[1] > 0) n = [-n[0], -n[1]];
        const o1 = FOUNDERS_CW_HW + 2.5, o2 = FOUNDERS_CW_HW + 8;
        // Stop short of the cross streets at both ends.
        const a1 = [a[0] + dx * 0.1, a[1] + dz * 0.1], b1 = [a[0] + dx * 0.9, a[1] + dz * 0.9];
        return [[a1[0] + n[0] * o1, a1[1] + n[1] * o1], [b1[0] + n[0] * o1, b1[1] + n[1] * o1], [b1[0] + n[0] * o2, b1[1] + n[1] * o2], [a1[0] + n[0] * o2, a1[1] + n[1] * o2]];
      });
    })(),
    harishonim: { f: frame(...centroid(hrW)), world: hrW },
    lifeguards: LIFEGUARD_POLYS.map((poly) => { const w = projPoly(poly); return { world: w, f: frame(...centroid(w), coastRy + Math.PI / 2) }; }), // face the sea (west)
    kiosk: { f: frame(...centroid(kioskW), coastRy + Math.PI / 2), world: kioskW },
    matkot: { f: frame(...P(MATKOT_LL), coastRy) },
    beachRy: coastRy,
    welcome: { f: frame(...P(WELCOME_LL), Math.PI / 2 + 0.35) }, // reads from Moshe Dayan Blvd (east)
  };
})();

// Round 5 layout (kept apart from L so the round-4 block stays readable).
const L5 = (() => {
  const az = projPoly(AZRIELI_POLY);
  // Azrieli: long axis (principal direction of the outline, pointing south-east) and the split
  // between the wing on the ground and the wing raised over the bus terminal (south-east 45%).
  const azF = frame(...centroid(az)), loc = toLocal(azF, az);
  let sxx = 0, szz = 0, sxz = 0;
  for (const [x, z] of loc) { sxx += x * x; szz += z * z; sxz += x * z; }
  const ang = 0.5 * Math.atan2(2 * sxz, sxx - szz);
  let u = [Math.cos(ang), Math.sin(ang)];
  if (u[0] < 0) u = [-u[0], -u[1]];
  const ss = loc.map((p) => p[0] * u[0] + p[1] * u[1]), s0 = Math.min(...ss), s1 = Math.max(...ss), sCut = s0 + 0.55 * (s1 - s0);
  const lower = clipHalf(loc, [u[0] * sCut, u[1] * sCut], [-u[0], -u[1]], 0), raised = clipHalf(loc, [u[0] * sCut, u[1] * sCut], u, 0);
  const W = (p) => p.map(([x, z]) => [x + azF.x, z + azF.z]);
  return {
    azrieli: { f: azF, world: az, u, s0, s1, sCut, lower, raised, lowerW: W(lower), raisedW: W(raised) },
    lookout: { f: frame(LOOKOUT_C[0], LOOKOUT_C[1], LOOKOUT_RY) },
    shikmaSkate: projPoly(SHIKMA_SKATE_POLY),
    shikmaKart: { f: frame(SHIKMA_KART.at[0], SHIKMA_KART.at[1], SHIKMA_KART.ry), w: SHIKMA_KART.w, d: SHIKMA_KART.d },
    eco: { f: frame(ECO_GARDEN.at[0], ECO_GARDEN.at[1], 0), w: ECO_GARDEN.w, d: ECO_GARDEN.d },
    clubs: COUNTRY_CLUBS.map((c) => ({ ...c, poolsW: c.pools.map(projPoly) })),
    rova: { square: projPoly(HAROVA_SQUARE), street: projPoly(HAROVA_STREET) },
    museum: MUSEUM_HOUSES.map((h) => ({ ...h, world: projPoly(h.poly) })),
    fuel: FUEL_STATIONS.map((st) => ({ ...st, f: frame(st.at[0], st.at[1], st.ry) })),
  };
})();

